import type { GaugeConfiguratorState, GaugeVisualLayout } from '@/entities/gauge-config/model/types';

const BASE_RADIUS_BY_SIZE: Record<GaugeConfiguratorState['nominalSize'], number> = {
  63: 90,
  100: 130,
  160: 160,
};

export const deriveVisualLayout = (config: GaugeConfiguratorState): GaugeVisualLayout => {
  const hasValve = config.accessories.valve.enabled;
  const hasSiphon = config.accessories.siphon.enabled;

  let cy = 300;
  let scale = 1;

  if (hasValve && hasSiphon) {
    cy = 180;
    scale = 0.8;
  } else if (hasValve || hasSiphon) {
    cy = 220;
    scale = 0.9;
  }

  const radius = BASE_RADIUS_BY_SIZE[config.nominalSize] * scale;
  const stemLen = (config.nominalSize === 63 ? 40 : 50) * scale;
  const stemWidth =
    config.connection.standard.includes('1/2') || config.connection.standard.includes('M20')
      ? 22 * scale
      : 16 * scale;

  const accessoryStackHeight =
    (hasValve ? 40 * scale : 0) +
    (hasSiphon ? (config.accessories.siphon.type.includes('Trumpet') ? 80 : 50) * scale : 15 * scale);

  return {
    svgSize: 600,
    cx: 300,
    cy,
    r: radius,
    rInner: radius * 0.92,
    rDial: radius * 0.85,
    stemLen,
    stemWidth,
    scale,
    pointerRotation: -30,
    redPointerRotation: 120,
    hasValve,
    hasSiphon,
    backConnectionRadius: Math.max(18, radius * 0.12),
    backConnectionLength: 34 * scale,
    accessoryStackHeight,
  };
};

