import { createGaugeDatasheetDocument } from '@/entities/pdf-datasheet/lib/build-gauge-pdf';
import type { ProjectInstrumentItem } from '@/entities/project-config/model/types';
import { buildPerInstrumentExportContext } from '@/services/project-reporting/lib/build-project-summary';

export const buildPerInstrumentPdfBlob = async (item: ProjectInstrumentItem, index: number) => {
  const context = buildPerInstrumentExportContext(item, index);
  const { doc } = await createGaugeDatasheetDocument(item.configuration, {
    headerTitle: 'ITEM DATA SHEET',
    headerSubtitle: 'BOURDON TUBE GAUGE SPECIFICATION',
    itemLabel: context.itemLabel,
    quantity: context.quantity,
    fileName: `${context.fileStem}.pdf`,
  });

  return {
    fileName: `${context.fileStem}.pdf`,
    blob: doc.output('blob'),
  };
};

