import { deriveModelName } from '@/entities/gauge-config/lib/derive-model';
import { selectHasCriticalValidationErrors } from '@/entities/gauge-config/model/selectors';
import type { GaugeConfiguratorState } from '@/entities/gauge-config/model/types';
import type {
  ProjectConfiguration,
  ProjectInstrumentItem,
  ProjectInstrumentSnapshot,
  ProjectItemStatus,
  ProjectSummaryRow,
} from '@/entities/project-config/model/types';

const buildAccessorySummary = (configuration: GaugeConfiguratorState) => {
  const accessories: string[] = [];

  if (configuration.accessories.valve.enabled) {
    accessories.push('Valve');
  }

  if (configuration.accessories.siphon.enabled) {
    accessories.push('Siphon');
  }

  return accessories.join(', ') || 'Base gauge';
};

const buildSelectedOptionsSummary = (configuration: GaugeConfiguratorState) => {
  const options: string[] = [];

  if (configuration.options.redPointer) {
    options.push('Red pointer');
  }

  if (configuration.options.oxygenService) {
    options.push('Oxygen service');
  }

  if (configuration.options.calibrationCert) {
    options.push('Calibration cert');
  }

  return options.length ? options.join(', ') : 'Standard options';
};

const buildDescriptionSummary = (configuration: GaugeConfiguratorState) =>
  [
    `NS ${configuration.nominalSize}`,
    `${configuration.rangeMin}..${configuration.rangeMax} ${configuration.unit}`,
    configuration.connection.location === 'Lower' ? 'Radial' : 'Back',
    configuration.connection.standard,
    configuration.case.material,
    configuration.case.filling !== 'Dry' ? configuration.case.filling : null,
    configuration.options.flange !== 'None' ? configuration.options.flange : null,
    configuration.accessories.valve.enabled
      ? `Valve ${configuration.accessories.valve.type} / ${configuration.accessories.valve.material}`
      : null,
    configuration.accessories.siphon.enabled
      ? `Siphon ${configuration.accessories.siphon.type} / ${configuration.accessories.siphon.material}`
      : null,
    buildSelectedOptionsSummary(configuration),
  ]
    .filter(Boolean)
    .join(' | ');

export const getProjectItemLabel = (item: ProjectInstrumentItem, index?: number) =>
  item.displayName.trim() ||
  item.configuration.project.tagNumber.trim() ||
  `Item ${typeof index === 'number' ? index + 1 : item.id.slice(0, 6)}`;

export const getProjectItemStatus = (item: ProjectInstrumentItem): ProjectItemStatus => {
  if (!Number.isInteger(item.quantity) || item.quantity < 1) {
    return 'error';
  }

  if (selectHasCriticalValidationErrors(item.configuration)) {
    return 'error';
  }

  if (!item.displayName.trim() && !item.configuration.project.tagNumber.trim()) {
    return 'incomplete';
  }

  if (!item.configuration.project.orderNumber.trim()) {
    return 'incomplete';
  }

  return 'valid';
};

export const buildProjectItemSnapshot = (item: ProjectInstrumentItem): ProjectInstrumentSnapshot => ({
  model: deriveModelName(item.configuration.case.filling),
  range: `${item.configuration.rangeMin}..${item.configuration.rangeMax} ${item.configuration.unit}`,
  connection:
    item.configuration.connection.location === 'Lower'
      ? `Radial / ${item.configuration.connection.standard}`
      : `Back / ${item.configuration.connection.standard}`,
  accessories: buildAccessorySummary(item.configuration),
  description: buildDescriptionSummary(item.configuration),
  status: getProjectItemStatus(item),
});

export const buildProjectSummaryRows = (project: ProjectConfiguration): ProjectSummaryRow[] =>
  project.items.map((item, index) => {
    const snapshot = buildProjectItemSnapshot(item);

    return {
      id: item.id,
      index: index + 1,
      label: getProjectItemLabel(item, index),
      model: snapshot.model,
      range: snapshot.range,
      connection: snapshot.connection,
      description: snapshot.description,
      quantity: item.quantity,
      status: snapshot.status,
      summary: snapshot.accessories,
    };
  });

export const getProjectTotalQuantity = (project: ProjectConfiguration) =>
  project.items.reduce((total, item) => total + item.quantity, 0);

export const getProjectStatusCounts = (project: ProjectConfiguration) =>
  buildProjectSummaryRows(project).reduce(
    (accumulator, row) => {
      accumulator[row.status] += 1;
      return accumulator;
    },
    { valid: 0, incomplete: 0, error: 0 },
  );
