import { defaultGaugeConfiguratorState } from '@/entities/gauge-config/model/defaults';
import type { GaugeConfiguratorState } from '@/entities/gauge-config/model/types';
import type { ProjectConfiguration, ProjectInstrumentItem } from '@/entities/project-config/model/types';

const createId = () =>
  typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
    ? crypto.randomUUID()
    : `item-${Math.random().toString(36).slice(2, 10)}`;

export const createProjectInstrumentItem = (
  configuration: GaugeConfiguratorState = defaultGaugeConfiguratorState,
  overrides: Partial<ProjectInstrumentItem> = {},
): ProjectInstrumentItem => {
  const timestamp = overrides.updatedAt ?? new Date().toISOString();

  return {
    id: overrides.id ?? createId(),
    displayName: overrides.displayName ?? '',
    quantity: overrides.quantity ?? 1,
    configuration,
    createdAt: overrides.createdAt ?? timestamp,
    updatedAt: timestamp,
  };
};

export const createDefaultProjectConfiguration = (): ProjectConfiguration => {
  const timestamp = new Date().toISOString();

  return {
    format: 'bourdon-gauge-project',
    version: 1,
    projectName: 'Gauge Project',
    createdAt: timestamp,
    updatedAt: timestamp,
    items: [createProjectInstrumentItem(defaultGaugeConfiguratorState, { createdAt: timestamp, updatedAt: timestamp })],
  };
};

