import { selectModelName } from '@/entities/gauge-config/model/selectors';
import type { GaugeConfiguratorState } from '@/entities/gauge-config/model/types';
import { serializeGaugeConfigExportPayload } from '@/services/config-io/export-config';

const slugify = (value: string) =>
  value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'gauge-config';

export const downloadGaugeConfig = (config: GaugeConfiguratorState) => {
  const payload = serializeGaugeConfigExportPayload(config);
  const blob = new Blob([payload], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  const modelName = slugify(selectModelName(config));

  anchor.href = url;
  anchor.download = `${modelName}-configuration.json`;
  anchor.click();

  URL.revokeObjectURL(url);
};
