import { buildProjectSummaryRows, getProjectStatusCounts, getProjectTotalQuantity } from '@/entities/project-config/lib/summary';
import type { ProjectConfiguration, ProjectInstrumentItem } from '@/entities/project-config/model/types';

export const selectActiveProjectItem = (
  project: ProjectConfiguration,
  activeItemId: string | null,
): ProjectInstrumentItem | null => project.items.find((item) => item.id === activeItemId) ?? null;

export const selectProjectSummaryRows = (project: ProjectConfiguration) => buildProjectSummaryRows(project);

export const selectProjectTotals = (project: ProjectConfiguration) => ({
  itemCount: project.items.length,
  quantityTotal: getProjectTotalQuantity(project),
  statuses: getProjectStatusCounts(project),
});

