import { normalizeConfig } from '@/entities/gauge-config/lib/normalize-config';
import type { GaugeConfiguratorState } from '@/entities/gauge-config/model/types';
import { GaugeConfigImportError } from '@/services/config-io/errors';
import { parseGaugeConfigExportPayload } from '@/services/config-io/schema';
import {
  GAUGE_CONFIG_FORMAT,
  GAUGE_CONFIG_VERSION,
  type GaugeConfigExportPayload,
} from '@/services/config-io/types';

export const buildGaugeConfigExportPayload = (
  config: GaugeConfiguratorState,
  exportedAt = new Date().toISOString(),
): GaugeConfigExportPayload => {
  const payload: GaugeConfigExportPayload = {
    format: GAUGE_CONFIG_FORMAT,
    version: GAUGE_CONFIG_VERSION,
    exportedAt,
    configuration: normalizeConfig(config),
  };
  const parsedPayload = parseGaugeConfigExportPayload(payload);

  if (!parsedPayload.success) {
    throw new GaugeConfigImportError(parsedPayload.error.issues[0]?.message ?? 'Configuration is invalid.');
  }

  return parsedPayload.data;
};

export const serializeGaugeConfigExportPayload = (config: GaugeConfiguratorState) =>
  JSON.stringify(buildGaugeConfigExportPayload(config), null, 2);
