import JSZip from 'jszip';
import { serializeGaugeConfigExportPayload } from '@/services/config-io/export-config';
import { serializeProjectConfiguration } from '@/services/project-io/export-project';
import type { ProjectConfiguration } from '@/entities/project-config/model/types';
import { buildPerInstrumentPdfBlob } from '@/services/project-reporting/lib/build-per-instrument-pdf';
import { buildProjectPdfBlob } from '@/services/project-reporting/lib/build-project-pdf';
import { buildProjectManifest } from '@/services/project-reporting/lib/build-project-summary';
import { slugifyFilePart } from '@/services/project-reporting/lib/file';

export const buildProjectZipBlob = async (project: ProjectConfiguration) => {
  const zip = new JSZip();
  const manifest = buildProjectManifest(project);
  const projectSlug = slugifyFilePart(project.projectName, 'gauge-project');
  const combinedPdf = await buildProjectPdfBlob(project);

  zip.file(`${projectSlug}-combined-report.pdf`, combinedPdf);
  zip.file(`${projectSlug}.json`, serializeProjectConfiguration(project));
  zip.file('manifest.json', JSON.stringify(manifest, null, 2));

  for (const [index, item] of project.items.entries()) {
    const baseName = `${String(index + 1).padStart(2, '0')}-${slugifyFilePart(manifest.items[index].label, 'item')}`;
    const itemFolder = zip.folder('items');

    itemFolder?.file(`${baseName}.json`, serializeGaugeConfigExportPayload(item.configuration));

    const itemPdf = await buildPerInstrumentPdfBlob(item, index);
    itemFolder?.file(itemPdf.fileName, itemPdf.blob);
  }

  return {
    fileName: `${projectSlug}-project-package.zip`,
    blob: await zip.generateAsync({ type: 'blob' }),
  };
};
