import { buildProjectSummaryRows, getProjectItemLabel } from '@/entities/project-config/lib/summary';
import { selectProjectTotals } from '@/entities/project-config/model/selectors';
import type { ProjectConfiguration, ProjectInstrumentItem, ProjectSummaryRow } from '@/entities/project-config/model/types';

export type ProjectBomRow = ProjectSummaryRow;

export const buildProjectBomRows = (project: ProjectConfiguration): ProjectBomRow[] =>
  buildProjectSummaryRows(project);

export const buildProjectExportReadiness = (project: ProjectConfiguration) => {
  const rows = buildProjectBomRows(project);

  if (!rows.length) {
    return { ready: false, message: 'Add at least one instrument before export.' };
  }

  const invalidRow = rows.find((row) => row.status === 'error');

  if (invalidRow) {
    return {
      ready: false,
      message: `Fix invalid item "${invalidRow.label}" before export.`,
    };
  }

  return { ready: true, message: null };
};

export const buildProjectManifest = (project: ProjectConfiguration) => {
  const totals = selectProjectTotals(project);

  return {
    itemCount: totals.itemCount,
    quantityTotal: totals.quantityTotal,
    items: project.items.map((item, index) => ({
      pathBase: `items/${String(index + 1).padStart(2, '0')}-${getProjectItemLabel(item, index)}`,
      label: getProjectItemLabel(item, index),
      quantity: item.quantity,
    })),
  };
};

export const buildPerInstrumentExportContext = (item: ProjectInstrumentItem, index: number) => ({
  itemLabel: getProjectItemLabel(item, index),
  quantity: item.quantity,
  fileStem: `${String(index + 1).padStart(2, '0')}-${getProjectItemLabel(item, index)}`,
});

