import { useEffect, useRef } from 'react';
import { useGaugeConfiguratorStore } from '@/entities/gauge-config/model/store';
import { useProjectWorkspaceStore } from '@/entities/project-config/model/store';
import { AppShell } from '@/widgets/app-shell/ui/AppShell';
import { ConfiguratorLayout } from '@/widgets/configurator-layout/ui/ConfiguratorLayout';
import { ConfiguratorSidebar } from '@/widgets/configurator-sidebar/ui/ConfiguratorSidebar';
import { ExportToolbar } from '@/widgets/export-toolbar/ui/ExportToolbar';
import { GaugePreviewStage } from '@/widgets/gauge-preview-stage/ui/GaugePreviewStage';

export const ConfiguratorPage = () => {
  const previewRef = useRef<HTMLDivElement>(null);
  const replaceConfig = useGaugeConfiguratorStore((state) => state.replaceConfig);
  const activeItemId = useProjectWorkspaceStore((state) => state.activeItemId);

  useEffect(() => {
    const activeItem = useProjectWorkspaceStore
      .getState()
      .project.items.find((item) => item.id === activeItemId);

    if (activeItem) {
      replaceConfig(activeItem.configuration);
    }
  }, [activeItemId, replaceConfig]);

  return (
    <AppShell header={<ExportToolbar previewRef={previewRef} />}>
      <ConfiguratorLayout
        sidebar={<ConfiguratorSidebar />}
        preview={<GaugePreviewStage previewRef={previewRef} />}
      />
    </AppShell>
  );
};
