import type { GaugeConfiguratorState } from '@/entities/gauge-config/model/types';
import { createGaugeDatasheetDocument } from '@/entities/pdf-datasheet/lib/build-gauge-pdf';
import { capturePreview } from '@/entities/pdf-datasheet/lib/capture-preview';

export const exportGaugeDatasheet = async (
  config: GaugeConfiguratorState,
  previewElement: HTMLElement,
) => {
  const sketchImage = await capturePreview(previewElement);
  const { doc, fileName } = await createGaugeDatasheetDocument(config, { sketchImage });
  doc.save(fileName);
};
