import { deriveModelName } from '@/entities/gauge-config/lib/derive-model';
import { defaultGaugeConfiguratorState } from '@/entities/gauge-config/model/defaults';
import { gaugeConfiguratorHydrationSchema } from '@/entities/gauge-config/model/schema';
import type { GaugeConfiguratorState } from '@/entities/gauge-config/model/types';

type PartialConfig = Partial<GaugeConfiguratorState>;

const sanitizeNumber = (value: number, fallback: number) => (Number.isFinite(value) ? value : fallback);

export const withDerivedFields = (config: GaugeConfiguratorState): GaugeConfiguratorState => ({
  ...config,
  rangeMin: sanitizeNumber(config.rangeMin, defaultGaugeConfiguratorState.rangeMin),
  rangeMax: sanitizeNumber(config.rangeMax, defaultGaugeConfiguratorState.rangeMax),
  project: {
    ...config.project,
    temperature: sanitizeNumber(config.project.temperature, defaultGaugeConfiguratorState.project.temperature),
  },
  model: deriveModelName(config.case.filling),
});

export const normalizeConfig = (payload: unknown): GaugeConfiguratorState => {
  const parsed = gaugeConfiguratorHydrationSchema.safeParse(payload);

  if (!parsed.success) {
    return defaultGaugeConfiguratorState;
  }

  const merged: GaugeConfiguratorState = {
    ...defaultGaugeConfiguratorState,
    ...(parsed.data as PartialConfig),
    connection: {
      ...defaultGaugeConfiguratorState.connection,
      ...parsed.data.connection,
    },
    case: {
      ...defaultGaugeConfiguratorState.case,
      ...parsed.data.case,
    },
    accessories: {
      siphon: {
        ...defaultGaugeConfiguratorState.accessories.siphon,
        ...parsed.data.accessories?.siphon,
      },
      valve: {
        ...defaultGaugeConfiguratorState.accessories.valve,
        ...parsed.data.accessories?.valve,
      },
    },
    options: {
      ...defaultGaugeConfiguratorState.options,
      ...parsed.data.options,
    },
    project: {
      ...defaultGaugeConfiguratorState.project,
      ...parsed.data.project,
    },
    technicalContent: parsed.data.technicalContent ?? defaultGaugeConfiguratorState.technicalContent,
  };

  return withDerivedFields(merged);
};
