import { ZodError } from 'zod';
import { normalizeConfig } from '@/entities/gauge-config/lib/normalize-config';
import { GaugeConfigImportError } from '@/services/config-io/errors';
import { parseGaugeConfigExportPayload } from '@/services/config-io/schema';
import { GAUGE_CONFIG_FORMAT, GAUGE_CONFIG_VERSION, type GaugeConfigImportResult } from '@/services/config-io/types';

const migrateConfigVersion = (payload: unknown) => {
  if (!payload || typeof payload !== 'object') {
    throw new GaugeConfigImportError('Imported file must contain a JSON object.');
  }

  const candidate = payload as Record<string, unknown>;

  if (candidate.format !== GAUGE_CONFIG_FORMAT) {
    throw new GaugeConfigImportError('Unsupported file format. Expected bourdon gauge JSON export.');
  }

  if (candidate.version !== GAUGE_CONFIG_VERSION) {
    throw new GaugeConfigImportError(`Unsupported JSON version: ${String(candidate.version)}.`);
  }

  return candidate;
};

const buildValidationMessage = (error: ZodError) => {
  const issue = error.issues[0];

  if (!issue) {
    return 'Imported configuration is invalid.';
  }

  if (issue.path.length === 0) {
    return issue.message;
  }

  return `${issue.path.join('.')} ${issue.message}`.trim();
};

export const importGaugeConfig = (fileContents: string): GaugeConfigImportResult => {
  let parsedJson: unknown;

  try {
    parsedJson = JSON.parse(fileContents);
  } catch {
    throw new GaugeConfigImportError('Invalid JSON file.');
  }

  const migratedPayload = migrateConfigVersion(parsedJson);
  const parsedPayload = parseGaugeConfigExportPayload(migratedPayload);

  if (!parsedPayload.success) {
    throw new GaugeConfigImportError(buildValidationMessage(parsedPayload.error));
  }

  return {
    payload: parsedPayload.data,
    config: normalizeConfig(parsedPayload.data.configuration),
  };
};

export { migrateConfigVersion };

