import { addFooter } from '@/entities/pdf-datasheet/lib/add-footer';
import { renderGaugeDatasheetIntoDocument } from '@/entities/pdf-datasheet/lib/build-gauge-pdf';
import type { ProjectConfiguration } from '@/entities/project-config/model/types';
import { buildProjectBomRows, buildPerInstrumentExportContext } from '@/services/project-reporting/lib/build-project-summary';

const renderBomPage = async (doc: import('jspdf').jsPDF, project: ProjectConfiguration) => {
  const rows = buildProjectBomRows(project);
  const margin = 16;
  const columns = [
    { key: 'index', label: '#', width: 8 },
    { key: 'label', label: 'Item', width: 18 },
    { key: 'model', label: 'Model', width: 18 },
    { key: 'range', label: 'Range', width: 18 },
    { key: 'connection', label: 'Conn.', width: 20 },
    { key: 'description', label: 'Description', width: 76 },
    { key: 'quantity', label: 'Qty', width: 8 },
    { key: 'status', label: 'St.', width: 12 },
  ] as const;
  let y = 20;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(18);
  doc.setTextColor(33, 150, 243);
  doc.text('PROJECT SPECIFICATION', margin, y);
  y += 8;
  doc.setFontSize(9);
  doc.setTextColor(100);
  doc.text(`${project.projectName} / ${rows.length} item(s)`, margin, y);
  y += 8;

  doc.setFillColor(245, 247, 250);
  doc.rect(margin, y, columns.reduce((total, column) => total + column.width, 0), 8, 'F');
  doc.setFontSize(8);
  doc.setTextColor(50);
  doc.setFont('helvetica', 'bold');

  let x = margin;
  columns.forEach((column) => {
    doc.text(column.label, x + 2, y + 5);
    x += column.width;
  });

  y += 8;
  doc.setFont('helvetica', 'normal');

  rows.forEach((row) => {
    if (y > 270) {
      doc.addPage();
      y = 20;
    }

    const values = {
      index: String(row.index),
      label: row.label,
      model: row.model,
      range: row.range,
      connection: row.connection,
      description: row.description,
      quantity: String(row.quantity),
      status: row.status === 'valid' ? 'OK' : row.status === 'incomplete' ? 'INC' : 'ERR',
    };

    const rowHeight =
      Math.max(
        ...columns.map((column) => doc.splitTextToSize(values[column.key], column.width - 4).length),
        1,
      ) * 4 + 3;

    if (y + rowHeight > 278) {
      doc.addPage();
      y = 20;
    }

    let currentX = margin;
    columns.forEach((column) => {
      doc.setDrawColor(232, 235, 240);
      doc.rect(currentX, y, column.width, rowHeight);
      const text = doc.splitTextToSize(values[column.key], column.width - 4);
      doc.text(text, currentX + 2, y + 4);
      currentX += column.width;
    });

    y += rowHeight;
  });

  y += 8;
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(40);
  doc.text(`Total quantity: ${rows.reduce((total, row) => total + row.quantity, 0)}`, margin, Math.min(y, 285));
};

export const buildProjectPdfBlob = async (project: ProjectConfiguration) => {
  const [{ jsPDF }] = await Promise.all([import('jspdf')]);
  const doc = new jsPDF({
    orientation: 'p',
    unit: 'mm',
    format: 'a4',
    compress: true,
  });

  await renderBomPage(doc, project);

  for (const [index, item] of project.items.entries()) {
    doc.addPage();
    await renderGaugeDatasheetIntoDocument(doc, item.configuration, {
      headerTitle: 'ITEM DETAIL',
      headerSubtitle: project.projectName,
      itemLabel: buildPerInstrumentExportContext(item, index).itemLabel,
      quantity: item.quantity,
      fileName: 'project-report.pdf',
      compact: true,
    });
  }

  const totalPages = doc.getNumberOfPages();
  for (let page = 1; page <= totalPages; page += 1) {
    addFooter(doc, page, totalPages);
  }

  return doc.output('blob');
};
