import { useState } from 'react';
import { Archive, Files } from 'lucide-react';
import { useProjectWorkspaceStore } from '@/entities/project-config/model/store';
import { buildProjectExportReadiness } from '@/services/project-reporting/lib/build-project-summary';
import { buildProjectPdfBlob } from '@/services/project-reporting/lib/build-project-pdf';
import { buildProjectZipBlob } from '@/services/project-reporting/lib/build-project-zip';
import { downloadBlob, slugifyFilePart } from '@/services/project-reporting/lib/file';
import { en } from '@/shared/i18n';
import { cn } from '@/shared/lib/cn';

type NoticeState =
  | { tone: 'success'; message: string }
  | { tone: 'error'; message: string }
  | null;

export const ProjectExportActions = () => {
  const project = useProjectWorkspaceStore((state) => state.project);
  const readiness = buildProjectExportReadiness(project);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
  const [isGeneratingZip, setIsGeneratingZip] = useState(false);
  const [notice, setNotice] = useState<NoticeState>(null);

  const exportCombinedPdf = async () => {
    if (!readiness.ready) {
      setNotice({ tone: 'error', message: readiness.message ?? en.projectWorkspace.exportBlocked });
      return;
    }

    setIsGeneratingPdf(true);
    setNotice(null);

    try {
      const blob = await buildProjectPdfBlob(project);
      downloadBlob(blob, `${slugifyFilePart(project.projectName, 'gauge-project')}-combined-report.pdf`);
      setNotice({ tone: 'success', message: en.projectWorkspace.exportPdfSuccess });
    } catch (error) {
      console.error(error);
      setNotice({ tone: 'error', message: en.projectWorkspace.exportPdfError });
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  const exportProjectZip = async () => {
    if (!readiness.ready) {
      setNotice({ tone: 'error', message: readiness.message ?? en.projectWorkspace.exportBlocked });
      return;
    }

    setIsGeneratingZip(true);
    setNotice(null);

    try {
      const archive = await buildProjectZipBlob(project);
      downloadBlob(archive.blob, archive.fileName);
      setNotice({ tone: 'success', message: en.projectWorkspace.exportZipSuccess });
    } catch (error) {
      console.error(error);
      setNotice({ tone: 'error', message: en.projectWorkspace.exportZipError });
    } finally {
      setIsGeneratingZip(false);
    }
  };

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap justify-end gap-3">
        <button
          type="button"
          onClick={exportCombinedPdf}
          disabled={isGeneratingPdf || isGeneratingZip}
          className="inline-flex items-center gap-2 rounded-2xl border border-cyan-400/20 bg-cyan-500/10 px-4 py-3 text-sm font-bold text-cyan-100 transition hover:bg-cyan-500/20 disabled:cursor-not-allowed disabled:opacity-50"
        >
          <Files size={16} />
          <span>{isGeneratingPdf ? en.projectWorkspace.exportingCombinedPdf : en.projectWorkspace.exportCombined}</span>
        </button>

        <button
          type="button"
          onClick={exportProjectZip}
          disabled={isGeneratingPdf || isGeneratingZip}
          className="inline-flex items-center gap-2 rounded-2xl border border-emerald-400/20 bg-emerald-500/10 px-4 py-3 text-sm font-bold text-emerald-100 transition hover:bg-emerald-500/20 disabled:cursor-not-allowed disabled:opacity-50"
        >
          <Archive size={16} />
          <span>{isGeneratingZip ? en.projectWorkspace.exportingZip : en.projectWorkspace.exportZip}</span>
        </button>
      </div>

      {!readiness.ready && !notice ? (
        <p className="max-w-[28rem] text-right text-sm text-amber-200">{readiness.message}</p>
      ) : null}

      {notice ? (
        <p
          role="status"
          className={cn(
            'max-w-[28rem] text-right text-sm',
            notice.tone === 'success' ? 'text-emerald-300' : 'text-rose-300',
          )}
        >
          {notice.message}
        </p>
      ) : null}
    </div>
  );
};

