import { useRef, useState, type ChangeEvent } from 'react';
import { Download, Upload } from 'lucide-react';
import { useGaugeConfiguratorStore } from '@/entities/gauge-config/model/store';
import { useProjectWorkspaceStore } from '@/entities/project-config/model/store';
import { GaugeConfigImportError } from '@/services/config-io/errors';
import { downloadGaugeConfig } from '@/services/config-io/download-config';
import { importGaugeConfig } from '@/services/config-io/import-config';
import { en } from '@/shared/i18n';
import { cn } from '@/shared/lib/cn';

type NoticeState =
  | { tone: 'success'; message: string }
  | { tone: 'error'; message: string }
  | null;

const readFileAsText = (file: File) =>
  typeof file.text === 'function'
    ? file.text()
    : new Promise<string>((resolve, reject) => {
        const reader = new FileReader();

        reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
        reader.onerror = () => reject(reader.error ?? new Error('Failed to read file.'));
        reader.readAsText(file);
      });

export const ConfigIoActions = () => {
  const config = useGaugeConfiguratorStore((state) => state.config);
  const replaceConfig = useGaugeConfiguratorStore((state) => state.replaceConfig);
  const activeItemId = useProjectWorkspaceStore((state) => state.activeItemId);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [notice, setNotice] = useState<NoticeState>(null);

  const handleExport = () => {
    try {
      downloadGaugeConfig(config);
      setNotice({ tone: 'success', message: en.header.exportJsonSuccess });
    } catch (error) {
      console.error(error);
      setNotice({ tone: 'error', message: en.header.exportJsonError });
    }
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleImportChange = async (event: ChangeEvent<HTMLInputElement>) => {
    const [file] = Array.from(event.target.files ?? []);
    event.target.value = '';

    if (!file) {
      return;
    }

    try {
      const fileContents = await readFileAsText(file);
      const imported = importGaugeConfig(fileContents);
      replaceConfig(imported.config);
      setNotice({ tone: 'success', message: en.header.importJsonSuccess });
    } catch (error) {
      if (error instanceof GaugeConfigImportError) {
        setNotice({ tone: 'error', message: error.message });
        return;
      }

      console.error(error);
      setNotice({ tone: 'error', message: en.header.importJsonError });
    }
  };

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap justify-end gap-3">
        <input
          ref={fileInputRef}
          type="file"
          accept="application/json,.json"
          className="hidden"
          onChange={handleImportChange}
        />

        <button
          type="button"
          onClick={handleImportClick}
          disabled={!activeItemId}
          className="inline-flex items-center gap-2 rounded-2xl border border-white/10 bg-white/5 px-4 py-3 text-sm font-bold text-slate-200 transition hover:bg-white/10"
        >
          <Upload size={16} />
          <span>{en.header.importJson}</span>
        </button>

        <button
          type="button"
          onClick={handleExport}
          disabled={!activeItemId}
          className="inline-flex items-center gap-2 rounded-2xl border border-cyan-400/20 bg-cyan-500/10 px-4 py-3 text-sm font-bold text-cyan-100 transition hover:bg-cyan-500/20"
        >
          <Download size={16} />
          <span>{en.header.exportJson}</span>
        </button>
      </div>

      {notice ? (
        <p
          role="status"
          className={cn(
            'max-w-[28rem] text-right text-sm',
            notice.tone === 'success' ? 'text-emerald-300' : 'text-rose-300',
          )}
        >
          {notice.message}
        </p>
      ) : !activeItemId ? (
        <p className="max-w-[28rem] text-right text-sm text-amber-200">{en.projectWorkspace.selectItemToExport}</p>
      ) : null}
    </div>
  );
};
