import { z } from 'zod';
import { gaugeConfiguratorStateSchema } from '@/entities/gauge-config/model/schema';
import { GAUGE_CONFIG_FORMAT, GAUGE_CONFIG_VERSION } from '@/services/config-io/types';

const rangeValidationMessage = 'Range max must be greater than range min.';

export const gaugeConfigExportPayloadSchema = z
  .object({
    format: z.literal(GAUGE_CONFIG_FORMAT),
    version: z.literal(GAUGE_CONFIG_VERSION),
    exportedAt: z.string().datetime(),
    configuration: gaugeConfiguratorStateSchema,
  })
  .superRefine(({ configuration }, ctx) => {
    if (configuration.rangeMax <= configuration.rangeMin) {
      ctx.addIssue({
        code: 'custom',
        message: rangeValidationMessage,
        path: ['configuration', 'rangeMax'],
      });
    }
  });

export const parseGaugeConfigExportPayload = (payload: unknown) =>
  gaugeConfigExportPayloadSchema.safeParse(payload);

export { rangeValidationMessage };
