import { create } from 'zustand';
import { normalizeConfig } from '@/entities/gauge-config/lib/normalize-config';
import type { GaugeConfiguratorState } from '@/entities/gauge-config/model/types';
import { createDefaultProjectConfiguration, createProjectInstrumentItem } from '@/entities/project-config/model/defaults';
import type { ProjectConfiguration } from '@/entities/project-config/model/types';

type MoveDirection = 'up' | 'down';

type ProjectWorkspaceStore = {
  project: ProjectConfiguration;
  activeItemId: string | null;
  setProjectName: (projectName: string) => void;
  addItem: (configuration?: GaugeConfiguratorState) => string;
  duplicateItem: (itemId: string) => string | null;
  removeItem: (itemId: string) => void;
  reorderItem: (itemId: string, direction: MoveDirection) => void;
  setActiveItem: (itemId: string | null) => void;
  setItemDisplayName: (itemId: string, displayName: string) => void;
  setItemQuantity: (itemId: string, quantity: number) => void;
  syncActiveConfig: (configuration: GaugeConfiguratorState) => void;
};

const initialProject = createDefaultProjectConfiguration();

const touchProject = (project: ProjectConfiguration): ProjectConfiguration => ({
  ...project,
  updatedAt: new Date().toISOString(),
});

const updateItem = (
  project: ProjectConfiguration,
  itemId: string,
  updater: (item: ProjectConfiguration['items'][number]) => ProjectConfiguration['items'][number],
) => ({
  ...touchProject(project),
  items: project.items.map((item) => (item.id === itemId ? updater(item) : item)),
});

export const useProjectWorkspaceStore = create<ProjectWorkspaceStore>((set) => ({
  project: initialProject,
  activeItemId: initialProject.items[0]?.id ?? null,
  setProjectName: (projectName) =>
    set((state) => ({
      project: {
        ...touchProject(state.project),
        projectName,
      },
    })),
  addItem: (configuration) => {
    const item = createProjectInstrumentItem(normalizeConfig(configuration));
    set((state) => ({
      project: {
        ...touchProject(state.project),
        items: [...state.project.items, item],
      },
      activeItemId: item.id,
    }));
    return item.id;
  },
  duplicateItem: (itemId) => {
    const sourceItem = useProjectWorkspaceStore.getState().project.items.find((item) => item.id === itemId);

    if (!sourceItem) {
      return null;
    }

    const duplicate = createProjectInstrumentItem(sourceItem.configuration, {
      displayName: sourceItem.displayName ? `${sourceItem.displayName} Copy` : '',
      quantity: sourceItem.quantity,
    });

    set((state) => {
      const sourceIndex = state.project.items.findIndex((item) => item.id === itemId);
      const items = [...state.project.items];
      items.splice(sourceIndex + 1, 0, duplicate);

      return {
        project: {
          ...touchProject(state.project),
          items,
        },
        activeItemId: duplicate.id,
      };
    });

    return duplicate.id;
  },
  removeItem: (itemId) =>
    set((state) => {
      const nextItems = state.project.items.filter((item) => item.id !== itemId);
      const nextActiveItemId =
        state.activeItemId === itemId ? (nextItems[0]?.id ?? null) : state.activeItemId;

      return {
        project: {
          ...touchProject(state.project),
          items: nextItems,
        },
        activeItemId: nextActiveItemId,
      };
    }),
  reorderItem: (itemId, direction) =>
    set((state) => {
      const currentIndex = state.project.items.findIndex((item) => item.id === itemId);
      const targetIndex = direction === 'up' ? currentIndex - 1 : currentIndex + 1;

      if (currentIndex < 0 || targetIndex < 0 || targetIndex >= state.project.items.length) {
        return state;
      }

      const items = [...state.project.items];
      const [item] = items.splice(currentIndex, 1);
      items.splice(targetIndex, 0, item);

      return {
        ...state,
        project: {
          ...touchProject(state.project),
          items,
        },
      };
    }),
  setActiveItem: (itemId) => set({ activeItemId: itemId }),
  setItemDisplayName: (itemId, displayName) =>
    set((state) => ({
      project: updateItem(state.project, itemId, (item) => ({
        ...item,
        displayName,
        updatedAt: new Date().toISOString(),
      })),
    })),
  setItemQuantity: (itemId, quantity) =>
    set((state) => ({
      project: updateItem(state.project, itemId, (item) => ({
        ...item,
        quantity,
        updatedAt: new Date().toISOString(),
      })),
    })),
  syncActiveConfig: (configuration) =>
    set((state) => {
      if (!state.activeItemId) {
        return state;
      }

      return {
        project: updateItem(state.project, state.activeItemId, (item) => ({
          ...item,
          configuration,
          updatedAt: new Date().toISOString(),
        })),
      };
    }),
}));
