import { useEffect, useState, type KeyboardEvent, type MouseEvent } from 'react';
import {
  ArrowDown,
  ArrowUp,
  Boxes,
  Copy,
  Download,
  FileJson,
  PackagePlus,
  Trash2,
} from 'lucide-react';
import { selectActiveProjectItem, selectProjectSummaryRows, selectProjectTotals } from '@/entities/project-config/model/selectors';
import { useProjectWorkspaceStore } from '@/entities/project-config/model/store';
import type { ProjectInstrumentItem, ProjectSummaryRow } from '@/entities/project-config/model/types';
import { serializeGaugeConfigExportPayload } from '@/services/config-io/export-config';
import { buildPerInstrumentPdfBlob } from '@/services/project-reporting/lib/build-per-instrument-pdf';
import { downloadBlob, slugifyFilePart } from '@/services/project-reporting/lib/file';
import { en } from '@/shared/i18n';
import { cn } from '@/shared/lib/cn';
import { Field } from '@/shared/ui/Field';
import { SectionCard } from '@/shared/ui/SectionCard';
import { StatusPill } from '@/shared/ui/StatusPill';
import { TextInput } from '@/shared/ui/TextInput';

const statusTone: Record<ProjectSummaryRow['status'], 'accent' | 'warning' | 'danger'> = {
  valid: 'accent',
  incomplete: 'warning',
  error: 'danger',
};

type QuantityInputProps = {
  itemId: string;
  quantity: number;
  onCommit: (itemId: string, quantity: number) => void;
};

const QuantityInput = ({ itemId, quantity, onCommit }: QuantityInputProps) => {
  const [draft, setDraft] = useState(String(quantity));

  useEffect(() => {
    setDraft(String(quantity));
  }, [quantity]);

  const commitDraft = () => {
    const nextValue = Number.parseInt(draft, 10);
    onCommit(itemId, Number.isInteger(nextValue) && nextValue > 0 ? nextValue : 1);
  };

  return (
    <TextInput
      value={draft}
      inputMode="numeric"
      aria-label={en.projectWorkspace.quantityAriaLabel(itemId)}
      className="w-20 text-center"
      onClick={(event) => event.stopPropagation()}
      onChange={(event) => setDraft(event.currentTarget.value.replace(/[^\d]/g, ''))}
      onBlur={commitDraft}
      onKeyDown={(event) => {
        if (event.key === 'Enter') {
          event.currentTarget.blur();
        }
      }}
    />
  );
};

const stopCardEvent = (event: MouseEvent<HTMLButtonElement>) => {
  event.stopPropagation();
};

type ProjectItemRowProps = {
  item: ProjectInstrumentItem;
  row: ProjectSummaryRow;
  isActive: boolean;
  isFirst: boolean;
  isLast: boolean;
  onSelect: () => void;
  onDuplicate: () => void;
  onRemove: () => void;
  onMoveUp: () => void;
  onMoveDown: () => void;
  onQuantityCommit: (itemId: string, quantity: number) => void;
};

const ProjectItemRow = ({
  item,
  row,
  isActive,
  isFirst,
  isLast,
  onSelect,
  onDuplicate,
  onRemove,
  onMoveUp,
  onMoveDown,
  onQuantityCommit,
}: ProjectItemRowProps) => {
  const setItemDisplayName = useProjectWorkspaceStore((state) => state.setItemDisplayName);
  const [isExportingPdf, setIsExportingPdf] = useState(false);
  const [isExportingJson, setIsExportingJson] = useState(false);

  const exportItemPdf = async (event: MouseEvent<HTMLButtonElement>) => {
    stopCardEvent(event);
    setIsExportingPdf(true);

    try {
      const { blob, fileName } = await buildPerInstrumentPdfBlob(item, row.index - 1);
      downloadBlob(blob, fileName);
    } finally {
      setIsExportingPdf(false);
    }
  };

  const exportItemJson = (event: MouseEvent<HTMLButtonElement>) => {
    stopCardEvent(event);
    setIsExportingJson(true);

    try {
      const blob = new Blob([serializeGaugeConfigExportPayload(item.configuration)], {
        type: 'application/json',
      });
      downloadBlob(blob, `${slugifyFilePart(row.label, `item-${row.index}`)}.json`);
    } finally {
      setIsExportingJson(false);
    }
  };

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={onSelect}
      onKeyDown={(event: KeyboardEvent<HTMLDivElement>) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault();
          onSelect();
        }
      }}
      className={cn(
        'w-full rounded-3xl border p-4 text-left transition',
        isActive
          ? 'border-orange-400/40 bg-orange-500/10 shadow-[0_0_20px_rgba(249,115,22,0.12)]'
          : 'border-white/6 bg-panelSoft/70 hover:border-white/12 hover:bg-panelSoft',
      )}
    >
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="space-y-2">
          <div className="flex flex-wrap items-center gap-2">
            <StatusPill tone="info">{`Item ${row.index}`}</StatusPill>
            <StatusPill tone={statusTone[row.status]}>{row.status}</StatusPill>
            {isActive ? <StatusPill tone="accent">{en.projectWorkspace.editing}</StatusPill> : null}
          </div>

          <TextInput
            value={item.displayName}
            onClick={(event) => event.stopPropagation()}
            onChange={(event) => setItemDisplayName(item.id, event.currentTarget.value)}
            placeholder={item.configuration.project.tagNumber || en.projectWorkspace.itemNamePlaceholder}
            aria-label={en.projectWorkspace.itemNameAriaLabel(row.index)}
            className="max-w-sm border-white/10 bg-transparent px-0 py-0 text-base font-bold text-white placeholder:text-slate-500"
          />

          <p className="text-sm text-slate-300">{`${row.model} / ${row.range}`}</p>
          <p className="text-xs uppercase tracking-[0.18em] text-slate-500">{`${row.connection} / ${row.summary}`}</p>
        </div>

        <div className="flex flex-col items-end gap-3">
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-bold uppercase tracking-[0.18em] text-slate-500">Qty</span>
            <QuantityInput itemId={item.id} quantity={item.quantity} onCommit={onQuantityCommit} />
          </div>

          <div className="flex flex-wrap justify-end gap-2">
            <button
              type="button"
              onClick={(event) => {
                stopCardEvent(event);
                onMoveUp();
              }}
              disabled={isFirst}
              aria-label={en.projectWorkspace.moveUpAriaLabel(row.index)}
              className="rounded-2xl border border-white/10 bg-white/5 p-2 text-slate-300 disabled:cursor-not-allowed disabled:opacity-40"
            >
              <ArrowUp size={14} />
            </button>
            <button
              type="button"
              onClick={(event) => {
                stopCardEvent(event);
                onMoveDown();
              }}
              disabled={isLast}
              aria-label={en.projectWorkspace.moveDownAriaLabel(row.index)}
              className="rounded-2xl border border-white/10 bg-white/5 p-2 text-slate-300 disabled:cursor-not-allowed disabled:opacity-40"
            >
              <ArrowDown size={14} />
            </button>
            <button
              type="button"
              onClick={(event) => {
                stopCardEvent(event);
                onDuplicate();
              }}
              aria-label={en.projectWorkspace.duplicateAriaLabel(row.index)}
              className="rounded-2xl border border-white/10 bg-white/5 p-2 text-slate-300"
            >
              <Copy size={14} />
            </button>
            <button
              type="button"
              onClick={exportItemJson}
              aria-label={en.projectWorkspace.exportJsonAriaLabel(row.index)}
              className="rounded-2xl border border-white/10 bg-white/5 p-2 text-slate-300"
            >
              <FileJson size={14} />
            </button>
            <button
              type="button"
              onClick={exportItemPdf}
              aria-label={en.projectWorkspace.exportPdfAriaLabel(row.index)}
              className="rounded-2xl border border-white/10 bg-white/5 p-2 text-slate-300"
            >
              <Download size={14} />
            </button>
            <button
              type="button"
              onClick={(event) => {
                stopCardEvent(event);
                onRemove();
              }}
              aria-label={en.projectWorkspace.removeAriaLabel(row.index)}
              className="rounded-2xl border border-rose-400/20 bg-rose-400/10 p-2 text-rose-200"
            >
              <Trash2 size={14} />
            </button>
          </div>

          {isExportingPdf || isExportingJson ? (
            <p className="text-xs text-slate-400">
              {isExportingPdf ? en.projectWorkspace.exportingPdf : en.projectWorkspace.exportingJson}
            </p>
          ) : null}
        </div>
      </div>
    </div>
  );
};

export const ProjectWorkspacePanel = () => {
  const project = useProjectWorkspaceStore((state) => state.project);
  const activeItemId = useProjectWorkspaceStore((state) => state.activeItemId);
  const setActiveItem = useProjectWorkspaceStore((state) => state.setActiveItem);
  const addItem = useProjectWorkspaceStore((state) => state.addItem);
  const duplicateItem = useProjectWorkspaceStore((state) => state.duplicateItem);
  const removeItem = useProjectWorkspaceStore((state) => state.removeItem);
  const reorderItem = useProjectWorkspaceStore((state) => state.reorderItem);
  const setItemQuantity = useProjectWorkspaceStore((state) => state.setItemQuantity);
  const setProjectName = useProjectWorkspaceStore((state) => state.setProjectName);
  const rows = selectProjectSummaryRows(project);
  const totals = selectProjectTotals(project);
  const activeItem = selectActiveProjectItem(project, activeItemId);

  return (
    <SectionCard
      title={en.projectWorkspace.title}
      icon={Boxes}
      accentClass="text-cyan-300"
      headerAction={
        <button
          type="button"
          onClick={() => addItem()}
          className="inline-flex items-center gap-2 rounded-2xl border border-cyan-400/20 bg-cyan-500/10 px-4 py-2 text-xs font-bold uppercase tracking-[0.18em] text-cyan-100"
        >
          <PackagePlus size={14} />
          <span>{en.projectWorkspace.addItem}</span>
        </button>
      }
    >
      <div className="space-y-5">
        <Field label={en.projectWorkspace.projectName} htmlFor="project-name">
          <TextInput
            id="project-name"
            value={project.projectName}
            onChange={(event) => setProjectName(event.currentTarget.value)}
            placeholder={en.projectWorkspace.projectNamePlaceholder}
          />
        </Field>

        <div className="flex flex-wrap gap-2">
          <StatusPill tone="info">{`${totals.itemCount} item(s)`}</StatusPill>
          <StatusPill>{`${totals.quantityTotal} total qty`}</StatusPill>
          {totals.statuses.error ? <StatusPill tone="danger">{`${totals.statuses.error} error`}</StatusPill> : null}
          {totals.statuses.incomplete ? (
            <StatusPill tone="warning">{`${totals.statuses.incomplete} incomplete`}</StatusPill>
          ) : null}
          {totals.statuses.valid ? <StatusPill tone="accent">{`${totals.statuses.valid} ready`}</StatusPill> : null}
        </div>

        {rows.length ? (
          <div className="space-y-3">
            {project.items.map((item, index) => (
              <ProjectItemRow
                key={item.id}
                item={item}
                row={rows[index]}
                isActive={item.id === activeItemId}
                isFirst={index === 0}
                isLast={index === project.items.length - 1}
                onSelect={() => setActiveItem(item.id)}
                onDuplicate={() => duplicateItem(item.id)}
                onRemove={() => removeItem(item.id)}
                onMoveUp={() => reorderItem(item.id, 'up')}
                onMoveDown={() => reorderItem(item.id, 'down')}
                onQuantityCommit={setItemQuantity}
              />
            ))}
          </div>
        ) : (
          <div className="rounded-3xl border border-dashed border-white/10 bg-panelSoft/60 px-5 py-6 text-sm text-slate-400">
            {en.projectWorkspace.empty}
          </div>
        )}

        <p className="text-xs uppercase tracking-[0.18em] text-slate-500">
          {activeItem
            ? `${en.projectWorkspace.activeItemLabel} ${activeItem.displayName || activeItem.configuration.project.tagNumber || en.projectWorkspace.untitledItem}`
            : en.projectWorkspace.noActiveItem}
        </p>
      </div>
    </SectionCard>
  );
};
